style.css:
/* Cute Pink Aesthetic Style with Disney Touch */

/* Body Background */
body {
    background-color: #ffcccb; /* Light pink background */
    font-family: 'Comic Sans MS', cursive, sans-serif; /* Cute font */
}

/* Text Color */
h1, h2, h3, h4, h5, h6 {
    color: #ff69b4; /* Hot pink for headings */
    text-align: center; /* Center align headings */
}

/* Paragraphs */
p {
    color: #333; /* Dark text for contrast */
    line-height: 1.6; /* Better readability */
    text-align: justify; /* Justify text */
}

/* Links */
a {
    color: #ff1493; /* Deep pink for links */
    text-decoration: none; /* Remove underline */
}

a:hover {
    text-decoration: underline; /* Underline on hover */
}

/* Buttons */
button {
    background-color: #ff69b4; /* Hot pink button background */
    color: white; /* black text on buttons */
    border: none; /* Remove border */
    border-radius: 5px; /* Rounded corners */
    padding: 10px 20px; /* Padding */
    cursor: pointer; /* Pointer cursor */
}

button:hover {
    background-color: #ff1493; /* Darker pink on hover */
}

/* Images */
img {
    border-radius: 10px; /* Rounded corners for images */
}

/* Custom Scrollbar */
::-webkit-scrollbar {
    width: 12px; /* Width of the scrollbar */
}

::-webkit-scrollbar-thumb {
    background-color: #ff69b4; /* Color of the scrollbar thumb */
    border-radius: 10px; /* Rounded corners for scrollbar thumb */
}

::-webkit-scrollbar-track {
    background: #ffe4e1; /* Background of the scrollbar track */
}
